import prismaMock from '../prisma-mock';
import {
  deleteComment,
  favoriteArticle,
  getArticles,
  getCommentsByArticle,
  unfavoriteArticle,
  updateComment,
} from '../../app/routes/article/article.service';

describe('ArticleService', () => {
  describe('getArticles', () => {
    beforeEach(() => {
      // @ts-ignore
      prismaMock.article.count.mockResolvedValue(0);
      // @ts-ignore
      prismaMock.article.findMany.mockResolvedValue([]);
    });

    test('should cap a limit above 50 at 50', async () => {
      // When
      await getArticles({ limit: '500' });

      // Then
      expect(prismaMock.article.findMany).toHaveBeenCalledWith(
        expect.objectContaining({ take: 50 }),
      );
    });

    test('should pass a limit of exactly 50 through unchanged', async () => {
      // When
      await getArticles({ limit: '50' });

      // Then
      expect(prismaMock.article.findMany).toHaveBeenCalledWith(
        expect.objectContaining({ take: 50 }),
      );
    });

    test('should pass a limit below 50 through unchanged', async () => {
      // When
      await getArticles({ limit: '20' });

      // Then
      expect(prismaMock.article.findMany).toHaveBeenCalledWith(
        expect.objectContaining({ take: 20 }),
      );
    });

    test('should use the default limit of 10 when no limit is sent', async () => {
      // When
      await getArticles({});

      // Then
      expect(prismaMock.article.findMany).toHaveBeenCalledWith(
        expect.objectContaining({ take: 10 }),
      );
    });

    test('should use the default limit of 10 when the limit is not a number', async () => {
      // When
      await getArticles({ limit: 'abc' });

      // Then
      expect(prismaMock.article.findMany).toHaveBeenCalledWith(
        expect.objectContaining({ take: 10 }),
      );
    });
  });

  describe('deleteComment', () => {
    test('should throw an error ', () => {
      // Given
      const id = 123;
      const idUser = 456;

      // When
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      expect(deleteComment(id, idUser)).rejects.toThrowError();
    });
  });

  describe('updateComment', () => {
    const slug = 'how-to-train-your-dragon-456';
    const commentId = 1;
    const userId = 456;

    const mockedUpdatedComment = {
      id: commentId,
      createdAt: new Date(),
      updatedAt: new Date(),
      editedAt: new Date(),
      body: 'new body',
      articleId: 123,
      authorId: userId,
      author: {
        username: 'RealWorld',
        bio: null,
        image: null,
        followedBy: [],
      },
    };

    test('should return a 422 error when the body is blank', async () => {
      // Given
      const body = '';

      // Then
      await expect(updateComment(body, slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 422,
      });
      expect(prismaMock.comment.findFirst).not.toHaveBeenCalled();
    });

    test('should look up the comment by id, article slug and author', async () => {
      // Given
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ id: commentId, createdAt: new Date() });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);

      // When
      await updateComment('new body', slug, commentId, userId);

      // Then
      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
        expect.objectContaining({
          where: {
            id: commentId,
            article: { slug },
            author: { id: userId },
          },
        }),
      );
    });

    test('should return a 404 error when the comment is not found or belongs to someone else', async () => {
      // Given
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue(null);

      // Then
      await expect(updateComment('new body', slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 404,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should return a 403 error and not update when the 30 minute edit window has passed', async () => {
      // Given
      const createdAt = new Date(Date.now() - 30 * 60 * 1000 - 1000);
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ id: commentId, createdAt });

      // Then
      await expect(updateComment('new body', slug, commentId, userId)).rejects.toMatchObject({
        errorCode: 403,
      });
      expect(prismaMock.comment.update).not.toHaveBeenCalled();
    });

    test('should update the body and set editedAt to the time of the edit', async () => {
      // Given
      // @ts-ignore
      prismaMock.comment.findFirst.mockResolvedValue({ id: commentId, createdAt: new Date() });
      // @ts-ignore
      prismaMock.comment.update.mockResolvedValue(mockedUpdatedComment);

      // When
      const result = await updateComment('new body', slug, commentId, userId);

      // Then
      expect(prismaMock.comment.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: commentId },
          data: expect.objectContaining({
            body: 'new body',
            editedAt: expect.any(Date),
          }),
        }),
      );
      expect(result).toHaveProperty('body', 'new body');
      expect(result).toHaveProperty('editedAt');
    });
  });

  describe('favoriteArticle', () => {
    test('should return the favorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      // @ts-ignore
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      // @ts-ignore
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(favoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(favoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
  describe('unfavoriteArticle', () => {
    test('should return the unfavorited article', async () => {
      // Given
      const slug = 'How-to-train-your-dragon';
      const username = 'RealWorld';

      const mockedUserResponse = {
        id: 123,
        username: 'RealWorld',
        email: 'realworld@me',
        password: '1234',
        bio: null,
        image: null,
        token: '',
        demo: false,
      };

      const mockedArticleResponse = {
        id: 123,
        slug: 'How-to-train-your-dragon',
        title: 'How to train your dragon',
        description: '',
        body: '',
        createdAt: new Date(),
        updatedAt: new Date(),
        authorId: 456,
        tagList: [],
        favoritedBy: [],
        author: {
          username: 'RealWorld',
          bio: null,
          image: null,
          followedBy: [],
        },
      };

      // When
      prismaMock.user.findUnique.mockResolvedValue(mockedUserResponse);
      prismaMock.article.update.mockResolvedValue(mockedArticleResponse);

      // Then
      await expect(unfavoriteArticle(slug, mockedUserResponse.id)).resolves.toHaveProperty(
        'favoritesCount',
      );
    });

    test('should throw an error if no user is found', async () => {
      // Given
      const id = 123;
      const slug = 'how-to-train-your-dragon';
      const username = 'RealWorld';

      // When
      prismaMock.user.findUnique.mockResolvedValue(null);

      // Then
      await expect(unfavoriteArticle(slug, id)).rejects.toThrowError();
    });
  });
});
